document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('#list'),days=document.querySelector('.route-days');if(!list||!days)return;const picker=document.createElement('div');picker.className='day-picker';picker.hidden=true;document.body.appendChild(picker);list.addEventListener('click',e=>{const row=e.target.closest('.choice');if(!row)return;const place=row.querySelector('b')?.textContent;if(!place)return;picker.innerHTML='<div><strong>Adicionar '+place+' em qual dia?</strong><div class="day-options"></div><button>Cancelar</button></div>';[...days.children].forEach((d,i)=>{const b=document.createElement('button');b.textContent='Dia '+(i+1);b.onclick=()=>{const strong=d.querySelector('strong');strong.textContent=strong.textContent+' + '+place;picker.hidden=true};picker.querySelector('.day-options').appendChild(b)});picker.hidden=false;picker.querySelector('div>button').onclick=()=>picker.hidden=true});const s=document.createElement('style');s.textContent='.day-picker{position:fixed;inset:0;background:rgba(20,43,58,.6);z-index:30;display:grid;place-items:center;padding:20px}.day-picker>div{background:#f7f4ec;border-radius:18px;padding:22px;max-width:360px;width:100%}.day-picker strong{display:block;margin-bottom:15px}.day-options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.day-options button,.day-picker>div>button{padding:11px;border:0;border-radius:9px;background:#fff;color:#142b3a;font-weight:700;cursor:pointer}.day-picker>div>button{margin-top:12px;width:100%;background:transparent;border:1px solid #c3d7d2}';document.head.appendChild(s)});
